Lemma PfTab_xpres2 : forall LB SP X m m', PfTab m -> xpres LB SP X m m' -> xoff_statics X -> PfTab m'.
Proof.
  intros LB SP X m m' T PRES FX. unfold PfTab in *.
  eapply xpres_rw_cells; [exact PRES| exact T|]. apply xclient_range_static2; [ .. | exact FX];
    unfold PF_TABPTR, RLIBC, RCTX, RERRNO, RSSP_GUARD, RGOT_SSP, RVMLOCK; cbn; lia.
Qed.

