Lemma FT_xpres2 : forall LB SP X m m', FT m -> xpres LB SP X m m' -> xoff_statics X -> FT m'.
Proof.
  intros LB SP X m m' T PRES FX. eapply FT_xpres; [exact PRES | exact T |].
  eapply Forall_impl; [| exact FX]. intros [u v] K. unfold G_FIELD_TABLE. cbn in *. lia.
Qed.
