(* [comment removed for export] *)
(* [comment removed for export] *)
Definition elems_ok (L : list Z) : Prop :=
  forall e, e ∈ L -> 0 < e /\ e + 48 <= hceil /\ (e + 48 <= 0x10000 \/ 0xb4000 <= e).

Lemma elemsW_hi : forall L A n, elems_ok L -> hceil <= A -> Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) (elemsW L).
Proof.
  intros L A n EL HA. apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (a & Euv & INa).
  injection Euv as <- <-. cbn. destruct (EL a ltac:(apply (proj2 (list_elem_of_In _ _)); exact INa)) as (K1 & K2 & K3). lia.
Qed.

Lemma elemsW_statics : forall L, elems_ok L -> xoff_statics (elemsW L).
Proof.
  intros L EL. apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (a & Euv & INa).
  injection Euv as <- <-. cbn. destruct (EL a ltac:(apply (proj2 (list_elem_of_In _ _)); exact INa)) as (K1 & K2 & K3). lia.
Qed.

Lemma elemsW_win : forall L p0 n, (forall e, e ∈ L -> e + 48 <= p0 \/ p0 + n <= e) ->
  Forall (fun iv : Z * Z => p0 + n <= fst iv \/ snd iv <= p0) (elemsW L).
Proof.
  intros L p0 n WL. apply Forall_forall. intros [u v] INuv. apply in_map_iff in INuv. destruct INuv as (a & Euv & INa).
  injection Euv as <- <-. cbn. destruct (WL a ltac:(apply (proj2 (list_elem_of_In _ _)); exact INa)); lia.
Qed.

Definition IPF_STACK : Z := IPF_FRAME + OTF_STACK.

(* [comment removed for export] *)
Definition ipf_X (P IN E : Z) (L0 : list Z) : list (Z * Z) :=
  (P, P + 128) :: (IN, IN + 8) :: (E, E + 24) :: (G_HTTP_CAT, G_HTTP_CAT + 64) :: (G_FIELD_TABLE, G_FIELD_TABLE + 3456) :: elemsW L0.

(* [comment removed for export] *)
Definition new_elems_off (LB0 : list block) (SP : Z) (L0 L1 : list Z) : Prop :=
  forall e, e ∈ L1 -> e ∈ L0 \/ (forall a k, rclient_range LB0 SP a k -> 0 <= k -> a + k <= e \/ e + 48 <= a).

(* [comment removed for export] *)
Definition lsub (L0 L1 : list Z) : Prop := forall e, e ∈ L0 -> e ∈ L1.
Definition lbn_own (L1 : list Z) (LBn : list block) : Prop := forall b, In b LBn -> blk_addr b ∈ L1 /\ 1 <= blk_size b.

Lemma lsub_refl : forall L, lsub L L.
Proof. intros L e He. exact He. Qed.
Lemma lbn_own_nil : forall L, lbn_own L [].
Proof. intros L b Hb. destruct Hb. Qed.

Lemma ipf_W_write_ok : forall LB lo (sp : word) P IN E,
  hceil <= lo -> bv_unsigned sp <= P -> bv_unsigned sp <= IN -> bv_unsigned sp <= E -> lo <= bv_unsigned sp ->
  Forall (rclient_write_ok LB) (ipf_W lo sp P IN E).
Proof.
  ltac2:(KReplay.run [|constr:(@Corelib.Init.Datatypes.list); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ref.RMalloc_iface_stmt.block); constr:(@Corelib.Numbers.BinNums.Z); constr:(@stdpp.bitvector.definitions.bv); constr:(@Corelib.Numbers.BinNums.Npos); constr:(@Corelib.Numbers.BinNums.xO); constr:(@Corelib.Numbers.BinNums.xH); constr:(@Stdlib.ZArith.BinInt.Z.le); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapCeil.hceil); constr:(HCEIL); constr:(@stdpp.bitvector.definitions.bv_unsigned); constr:(@Corelib.Lists.ListDef.Forall_cons); constr:(@Corelib.Init.Datatypes.prod); constr:(@Corelib.Init.Logic.or); constr:(@Corelib.Init.Datatypes.fst); constr:(@Corelib.Init.Logic.and); constr:(@Corelib.Numbers.BinNums.Zpos); constr:(@Corelib.Numbers.BinNums.xI); constr:(@Corelib.Init.Datatypes.snd); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Corelib.Init.Logic.ex); constr:(@Stdlib.Lists.List.In); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ref.RMalloc_iface_stmt.blk_addr); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ref.RMalloc_iface_stmt.blk_size); constr:(@Corelib.Init.Datatypes.pair); constr:(@Corelib.Init.Datatypes.cons); constr:(@Corelib.Init.Datatypes.nil); constr:(@Corelib.Init.Logic.or_introl); constr:(@Stdlib.micromega.ZMicromega.ZArithProof); constr:(@Stdlib.micromega.VarMap.Branch); constr:(@Stdlib.micromega.VarMap.Elt); constr:(@Stdlib.micromega.VarMap.Empty); constr:(@Stdlib.micromega.VarMap.t); constr:(@Stdlib.micromega.Tauto.IMPL); constr:(@Stdlib.micromega.RingMicromega.Formula); constr:(@Stdlib.micromega.Tauto.eKind); constr:(@Corelib.Init.Datatypes.unit); constr:(@Stdlib.micromega.Tauto.isProp); constr:(@Stdlib.micromega.Tauto.A); constr:(@Stdlib.micromega.RingMicromega.Build_Formula); constr:(@Stdlib.micromega.EnvRing.PEX); constr:(@Stdlib.micromega.RingMicromega.OpLe); constr:(@Corelib.Init.Datatypes.tt); constr:(@Corelib.Init.Datatypes.None); constr:(@Stdlib.micromega.Tauto.BFormula); constr:(@Stdlib.microm