Lemma ipf_W_pstatic : forall lo (sp : word) P IN E,
  hceil <= lo -> bv_unsigned sp <= P -> bv_unsigned sp <= IN -> bv_unsigned sp <= E ->
  (P + 256 <= IN \/ IN + 8 <= P) -> (P + 256 <= E \/ E + 24 <= P) -> lo <= bv_unsigned sp ->
  pstaticW (P + 80) (ipf_W lo sp P IN E).
Proof.
  intros lo sp P IN E H1 H2 H3 H4 H5 H6 H7. unfold pstaticW, ipf_W, G_HTTP_CAT, G_FIELD_TABLE.
  constructor; [left; cbn; lia|]. constructor; [left; cbn; lia|]. constructor; [left; cbn; lia|]. constructor; [left; cbn; lia|].
  constructor; [right; cbn; lia|]. constructor; [right; cbn; lia|]. constructor.
Qed.

Lemma dof_core_trans : forall c1 c2 c3, dof_core c1 c2 -> dof_core c2 c3 -> dof_core c1 c3.
Proof.
  intros c1 c2 c3 (A1 & A2 & A3 & A4 & A5 & A6 & A7 & A8) (B1 & B2 & B3 & B4 & B5 & B6 & B7 & B8). unfold dof_core.
  rewrite B1, B2, B3, B4, B5. repeat split; auto; lia.
Qed.

Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

Lemma elems_ok_of : forall s LB m Fa S L ns ls em,
  hs_RHEAP H s LB m -> FieldsC m Fa S L ns ls em -> FieldsOwn LB em -> elems_ok L /\ elems_heap em.
Proof.
  intros s LB m Fa S L ns ls em HP FC OWN. pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LE & EOK & _).
  assert (K : forall e d, em !! e = Some d -> 0 < e /\ e + esize d <= hceil /\ (e + esize d <= 0x10000 \/ 0xb4000 <= e) /\ 60 <= esize d).
  { intros e d Le. destruct (OWN e d Le) as [pe [INb _]]. destruct (hh_blocks H HH _ _ _ _ HP INb) as (Q1 & _ & _ & Q4 & Q5). cbn in Q1, Q4, Q5.
    pose proof (esize_ge d). repeat split; auto. }
  split.
  - intros e He. apply LE in He. destruct (em !! e) as [d|] eqn:Le; [| exfalso; exact (is_Some_None He)].
    destruct (K e d Le) as (K1 & K2 & K3 & K4). lia.
  - intros e d Le. destruct (K e d Le) as (K1 & K2 & K3 & K4). lia.
Qed.

(* [comment removed for export] *)
Definition ipf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (mo : Model) (LB : list block) (P IN E lo B : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (L0 : list Z) (mb : byte) : config -> Prop :=
  fun cf => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState)
                   (c' : pcore) (q' : Z) (E' : ecv) (LBn : list block) S' L' ns' ls' em' (g' : bool),
    cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ hs_KREL H s' (cfg_model cf) /\ hs_MPRES H mo (cfg_model cf)
    /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
    /\ hs_RHEAP H s' (LBn ++ LB) m'
    /\ FieldsC m' (P + 80) S' L' ns' ls' em' /\ FieldsOwn (LBn ++ LB) em' /\ new_elems_off LB (bv_unsigned sp) L0 L'
    /\ lsub L0 L' /\ lbn_own L' LBn
    /\ xpres LB (bv_unsigned sp) (ipf_X P IN E L0) m m'
    /\ rw_cells rsegs m' P (ParserCoreCells c' pad7 pad2) /\ dof_core c c'
    /\ rw_cells rsegs m' IN [C8 (wz q')] /\ p0 <= q' <= p0 + Z.of_nat (length bs)
    /\ rw_cells rsegs m' E (ErrCodeCells E') /\ (E' = EC_clear \/ http_fail E') /\ (E' = EC_clear -> p0 + 2 <= q')
    /\ rw_cells rsegs m' (P + 242) [C1 mb]
    /\ bytes_at rsegs m' p0 bs /\ PfTab m' /\ (FieldTabZero m' \/ FT m') /\ FTInit m' /\ HttpCat m' g' /\ XStatics m'
    /\ lb_bytes LBn <= 17 * (q' - p0) /\ 4 * Z.of_nat (length LBn) <= q' - p0.

Definition ipf_stmt : Prop :=
  forall (ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model) (s : PState) (LB : list block)
         (P IN E lo B : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (g : bool) (errv : word)
         (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (mb : byte),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells rsegs m IN [C8 (wz p0)] ->
  rw_cells rsegs m E (ErrCodeCells EC_clear) ->
  rw_cells rsegs m (P + 242) [C1 mb] ->
  FieldsC m (P + 80) S L ns ls em -> FieldsOwn LB em ->
  (forall e, e ∈ L -> e + 48 <= p0 \/ p0 + Z.of_nat (length bs) <= e) ->
  bytes_at rsegs m p0 bs -> rclient_range LB (bv_unsigned sp) p0 (Z.of_nat (length bs)) ->
  PfTab m -> (FieldTabZero m \/ FT m) -> FTInit m -> HttpCat m g -> XStatics m ->
  ipf_pure sp P IN E lo c p0 bs ->
  hs_RHEAP H s LB m -> hs_KREL H s mo ->
  lb_bytes LB + 17 * Z.of_nat (length bs) <= hs_LIVE_MAX H -> Z.of_nat (length LB) + Z.of_nat (length bs) / 4 <= hs_LIVE_CNT_MAX H ->
  hs_rauxv_ok H m B -> bv_unsigned sp <= B -> P + 256 <= B -> IN + 8 <= B -> E + 24 <= B -> B <= 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - IPF_STACK ->
  rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
  hs_SR H (ipf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m mo LB P IN E lo B c pad7 pad2 p0 bs L mb)
    (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
                     s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_BP_INNER_PARSE_FIELDS) fc None m (seg_rom rsegs)) mo).

(* [comment removed for export] *)
Definition ipf_at_vcall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P IN E lo B : Z) (c0 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (L0 : list Z) (mb : byte) (p : Z) (cf : config) : Prop :=
  exists (t0 t1 t2 t3 t4 t5 t6 : word) (m1 : mem) (c2 : pcore) (g1 : bool) (q p' f nlen vptr vlen bsz : Z) (nbs vbs j16 jt bb : list byte)
         (st1 : PState) (LBn : list block) (S1 L1 : list Z) (ns1 : NS) (ls1 : LS) (em1 : gmap Z elt) (errv1 : word),
    cfg_ms cf = MS (mkR (wz IPF_VRET) (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN)
                     (wz P) (wz f) (wz p) (wz nlen) (wz vptr) (wz vlen) (wz E) (wz (ipf_slot_target (pc_state c0)))
                     (wz (p0 + Z.of_nat (length bs))) (wz P) (wz G_FIELD_TABLE_GUARD) (wz G_FIELD_TABLE) (wz f) (wz nlen)
                     (Z_to_bv 64 (bv_unsigned sp + -128)) (wz 13) (wz 10) (wz 1) t3 t4 t5 t6)
                F (wz (ipf_slot_target (pc_state c0))) fc None m1 (seg_rom rsegs)
    /\ hs_KREL H st1 (cfg_model cf) /\ hs_MPRES H mo0 (cfg_model cf)
    /\ mem_inv rsegs m1 /\ stk rsegs m1 lo (bv_unsigned sp + -4288)
    /\ rw_cells rsegs m1 (errno_addr tp) [C4 errv1] /\ hs_rauxv_ok H m1 B
    /\ hs_RHEAP H st1 (LBn ++ LB0) m1
    /\ FieldsC m1 (P + 80) S1 L1 ns1 ls1 em1 /\ FieldsOwn (LBn ++ LB0) em1 /\ new_elems_off LB0 (bv_unsigned sp) L0 L1
    /\ lsub L0 L1 /\ lbn_own L1 LBn
    /\ (forall e, e ∈ L1 -> e + 48 <= p0 \/ p0 + Z.of_nat (length bs) <= e)
    /\ xpres LB0 (bv_unsigned sp) (ipf_X P IN E L0) m0 m1
    /\ lb_bytes LBn <= 17 * (p - p0) /\ 4 * Z.of_nat (length LBn) <= p - p0
    /\ ipf_frame m1 sp j16 jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)]
    /\ rw_cells rsegs m1 (bv_unsigned sp + -104) (map C8 (ipf_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra))
    /\ rw_cells rsegs m1 P (ParserCoreCells c2 pad7 pad2) /\ dof_core c0 c2
