Local Ltac cb_transport XP3 F16 TMP PP BF VL NM FRhi PC IT MB WIN PFT FI HC XS XHI XST XWIN RCR1 :=
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 F16 ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as F16';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 TMP ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as TMP';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 PP ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as PP';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 BF ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as BF';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 VL ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as VL';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 NM ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as NM';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 FRhi ltac:(lia) ltac:(cbn [cells_size csize Nat.add length map ipf_sv]; apply XHI; lia)) as FRhi';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 PC ltac:(lia) ltac:(unfold ParserCoreCells; cbn [cells_size csize Nat.add length]; apply XHI; lia)) as PC';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 IT ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as IT';
  pose proof (rw_cells_xpres_hi _ _ _ _ _ _ _ XP3 MB ltac:(lia) ltac:(cbn [cells_size csize Nat.add length]; apply XHI; lia)) as MB';
  pose proof (bytes_at_xpres _ _ _ _ _ _ _ XP3 WIN RCR1 XWIN) as WIN';
  pose proof (PfTab_xpres2 _ _ _ _ _ PFT XP3 XST) as PFT';
  pose proof (FTInit_xpres2 _ _ _ _ _ FI XP3 XST) as FI';
  pose proof (HttpCat_xpres2 _ _ _ _ _ _ HC XP3 XST) as HC';
  pose proof (XStatics_xpres2 _ _ _ _ _ XS XP3 XST) as XS';
  clear F16 TMP PP BF VL NM FRhi PC IT MB WIN PFT FI HC XS.

Lemma rclient_addr_range1 : forall LB SP a, rclient_addr LB SP a -> rclient_range LB SP a 1.
Proof.
  intros LB SP a [K|[[K1 K2]|(b & Hb & K)]].
  - left; lia.
  - right; left. unfold ralloc_static, RLIBC, RCTX, RERRNO, RSSP_GUARD, RGOT_SSP, RVMLOCK in *. lia.
  - right; right. exists b. split; [exact Hb| lia].
Qed.

(* [comment removed for export] *)
Lemma ipf_xclient_step : forall LB0 LBn (sp : word) P IN E L0 L1 a,
  new_elems_off LB0 (bv_unsigned sp) L0 L1 ->
  xclient LB0 (bv_unsigned sp) (ipf_X P IN E L0) a ->
  xclient (LBn ++ LB0) (bv_unsigned sp + -4288) ((E, E + 24) :: (P + 80, P + 128) :: elemsW L1) a.
Proof.
  intros LB0 LBn sp P IN E L0 L1 a NEW [RC NX]. split.
  - destruct RC as [K|[K|(b & Hb & K)]]; [left; lia | right; left; exact K | right; right; exists b; split; [apply in_or_app; right; exact Hb | exact K]].
  - unfold ipf_X in NX. cbn in NX. cbn. intros [K|[K|K]]; [apply NX; lia | apply NX; lia |].
    apply rin_ivs_elemsW in K. destruct K as (e & INe & Ke).
    destruct (NEW e ltac:(apply (proj2 (list_elem_of_In _ _)); exact INe)) as [OLD | OFF].
    + apply NX. do 5 right. apply rin_ivs_elemsW. exists e. split; [apply (proj1 (list_elem_of_In _ _)); exact OLD | exact Ke].
    + destruct (OFF a 1 (rclient_addr_range1 _ _ _ RC) ltac:(lia)); lia.
Qed.

