(* [comment removed for export] *)
Lemma ipf_round : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P IN E lo B : Z) (c0 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (L0 : list Z) (mb : byte) (p : Z) (cf : config),
  ipf_static sp tp LB0 P IN E lo B c0 p0 bs ->
  ipf_at_vcall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P IN E lo B c0 pad7 pad2 p0 bs L0 mb p cf ->
  hs_SR H (fun cf' => ipf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P IN E lo B c0 pad7 pad2 p0 bs L0 mb cf'
                      \/ exists p2, p + 4 <= p2
                         /\ ipf_at_vcall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P IN E lo B c0 pad7 pad2 p0 bs L0 mb p2 cf') cf.
Proof.
  intros until cf. intros STAT AV.
  eapply (hh_seq H HH); [eapply ipf_cb; [exact STAT | exact AV] |].
  intros cf' (p' & LE & AC). eapply (hh_mono H HH); [eapply ipf_tail; [exact STAT | exact AC] |].
  intros cf'' [K|K]; [left; exact K | right; exists p'; split; [exact LE | exact K]].
Qed.

(* [comment removed for export] *)
Lemma ipf_loop : forall (n : nat) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P IN E lo B : Z) (c0 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (L0 : list Z) (mb : byte) (p : Z) (cf : config),
  ipf_static sp tp LB0 P IN E lo B c0 p0 bs ->
  p0 + Z.of_nat (length bs) - p <= Z.of_nat n ->
  ipf_at_vcall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P IN E lo B c0 pad7 pad2 p0 bs L0 mb p cf ->
  hs_SR H (ipf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P IN E lo B c0 pad7 pad2 p0 bs L0 mb) cf.
Proof.
  induction n as [|n IH]; intros until cf; intros STAT MEAS AV.
  - exfalso. destruct cf as [ms mo]. unfold ipf_at_vcall in AV. cbn [cfg_ms cfg_model] in AV.
    destruct AV as (t0 & t1 & t2 & t3 & t4 & t5 & t6 & m1 & c2 & g1 & q & p' & f & nlen & vptr & vlen & bsz & nbs & vbs & j16 & jt & bb
                  & st1 & LBn & S1 & L1 & ns1 & ls1 & em1 & errv1 & AV).
    repeat match type of AV with _ /\ _ => let K := fresh "K" in destruct AV as [K AV] end.
    lazymatch goal with PS : pf_succ _ _ _ _ _ _ _ _ |- _ => unfold pf_succ in PS; cbn in MEAS; lia end.
  - eapply (hh_seq H HH); [eapply ipf_round; [exact STAT | exact AV] |].
    intros cf' [K | (p2 & LE & AV2)]; [apply (hh_done H HH); exact K |].
    rewrite Nat2Z.inj_succ in MEAS. eapply IH; [exact STAT | | exact AV2]. lia.
Qed.

(* [comment removed for export] *)
